export function getPoolStaticDataBySlug(slug: string): PoolStaticDetail | undefined {
  if (!slug) return undefined;
  const normalized = slug.toLowerCase().trim();

  // Direct match on key
  if (POOLS_STATIC_DATA[normalized]) {
    return POOLS_STATIC_DATA[normalized];
  }

  // Match by slug or alias
  for (const item of Object.values(POOLS_STATIC_DATA)) {
    if (
      item.slug.toLowerCase() === normalized ||
      item.aliases.some((a) => a.toLowerCase() === normalized)
    ) {
      return item;
    }
  }

  // Substring match fallback (e.g. if slug is "water-features" or "water-features-dubai")
  for (const item of Object.values(POOLS_STATIC_DATA)) {
    if (
      normalized.includes(item.slug.toLowerCase()) ||
      item.slug.toLowerCase().includes(normalized)
    ) {
      return item;
    }
  }

  return undefined;
}

export function getAllStaticPoolSlugs(): string[] {
  const slugs: string[] = [];
  for (const item of Object.values(POOLS_STATIC_DATA)) {
    slugs.push(item.slug);
    item.aliases.forEach((a) => slugs.push(a));
  }
  return Array.from(new Set(slugs));
}
